void dmc_config_prech ( struct mem_timings * mem , uint32_t * directcmd ) { int channel , chip ; for ( channel = 0 ; channel < mem -> dmc_channels ; channel ++ ) { cfs_time_t mask ; mask = channel << DIRECT_CMD_CHANNEL_SHIFT ; for ( chip = 0 ; chip < mem -> chips_per_channel ; chip ++ ) { mask |= chip << DIRECT_CMD_CHIP_SHIFT ; writel ( DIRECT_CMD_PALL | mask , directcmd ) ; sdelay ( 0x10000 ) ; } } } 